import limited_client as robot
import numpy as np
from PIL import Image
for c in range(4):
 o=robot.observe(camera=c)
 Image.fromarray(o['rgb']).save(f'/app/output/refresh102-{c}.png')
 print('\nCAM',c,'tcp',o['robot']['tcp_position'],'fingers',o['robot']['gripper_positions'])
 if c in (0,1,2):
  if c==0: crop=(120,260,300,390)
  elif c==1: crop=(100,250,280,410)
  else: crop=(120,220,360,335)
  Image.fromarray(o['rgb']).crop(crop).resize(((crop[2]-crop[0])*4,(crop[3]-crop[1])*4)).save(f'/app/output/refresh102-{c}-zoom.png')
  T=o['camera_to_world']; K=o['intrinsic']; d=o['depth_m']
  print('K',K.tolist())
  if c==2:
   for x,y in [(164,250),(164,260),(211,275),(263,270),(318,280),(318,290),(330,300)]:
    z=float(d[y,x]); p=np.linalg.inv(K)@np.array([x,y,1.])*z; w=T@np.r_[p,1.]
    print((x,y),o['rgb'][y,x].tolist(),round(z,3),np.round(w[:3],3).tolist())
print('STATUS',robot.status())
